import{_ as s,l as n,o as e,c as o,v as t,p as l,x as i,d as p,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"点过程与久期建模","description":"","frontmatter":{"title":"点过程与久期建模","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/point-process-durations.md","filePath":"quant/point-process-durations.md","lastUpdated":1789023840000}'),E={name:"quant/point-process-durations.md"};function h(u,a,m,c,_,B){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="点过程与久期建模" tabindex="-1">点过程与久期建模 <a class="header-anchor" href="#点过程与久期建模" aria-label="Permalink to &quot;点过程与久期建模&quot;">​</a></h1><div class="epigraph"><p>把成交当成随机时刻上的点，建模的是强度或相邻等待时间；价格平方加总是另一条轴，两套时钟不要混在同一方程里假装同质。</p><footer>—— Engle and Russell, Autoregressive Conditional Duration, Econometrica, 1998；强度一侧的 Hawkes 传统见 Hawkes, 1971</footer></div><p><a href="/quant/jumps-news">跳跃与新闻</a> 把某些点标了值（跳幅度、意外）。其余大多数点只是「发生了成交」。Engle–Russell 的 ACD 对久期 \\(x_i=t_i-t_{i-1}\\) 写条件均值；Hawkes 对强度 \\(\\lambda(t)\\) 写自激励。<a href="/quant/acd-duration">ACD 自回归条件久期</a> 已展开 ACD(1,1) 的估计与诊断。本课在高频单元里补<strong>缺口</strong>：点过程与 RV/核的关系、新闻如何进入强度、以及久期模型不回答「下一笔什么价」。下一课把时钟从墙钟换成成交量/业务时间，点过程的 \\(t\\) 本身被变形。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日历网格 GARCH 在空档插入零收益，把「没成交」当成一次观测。点过程的样本是事件。问题是选强度还是久期：Hawkes 便于多元互激励与分支比；ACD 便于诊断标准化久期 \\(x_i/\\psi_i\\)。两者在规则条件下可翻译，但估计与检验不同。对象还要声明：成交、报价修订、还是价格变动久期。混用则 \\(\\psi\\) 不可比。</p><p>新闻：在已知时刻让 \\(\\lambda(t)\\) 乘季节再乘公告抬升，或在 ACD 里加干预。这把上一课的日历变成强度的协变量，而不是把公告当一次回归的 \\(D_t\\) 就算完——因为公告后一串短久期是过程，不是单点。</p><h3 id="与-rv-的接口" tabindex="-1">与 RV 的接口 <a class="header-anchor" href="#与-rv-的接口" aria-label="Permalink to &quot;与 RV 的接口&quot;">​</a></h3><p>给定路径，RV 是变换。点过程描述事件到达；到达越密，同样墙钟里 \\(n\\) 越大，噪声项 \\(2n\\sigma_\\varepsilon^2\\) 越大。繁忙时朴素 RV 更噪，这是内生采样。业务时间课用成交量变形减轻这种异质。本课先承认：\\(n\\) 是点过程的实现，不是固定实验设计。</p><p><span class="marginnote">午休必须切断点过程，不能把上午最后一笔到下午第一笔当成一个 \\(x_i\\)。隔夜同理。这与季节课、刷新课同一会话边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>ACD。</strong> 见已有课：\\(\\psi_i=\\omega+\\alpha x_{i-1}+\\beta\\psi_{i-1}\\)，指数或 Weibull 新息，诊断标准化久期的 ACF。本课强调：把宏观哑元、季节（日内钟）放进 \\(\\psi\\)，再谈剩余自激励。否则 \\(\\alpha+\\beta\\) 吸收 U 形。</p><p><strong>Hawkes。</strong> \\(\\lambda(t)=\\mu+\\int_0^t \\phi(t-s)dN_s\\)，核 \\(\\phi\\) 指数时分支比 \\(\\int\\phi\\)。分支比近 1 则内生激发强，接近临界。新闻可写成 \\(\\mu(t)\\) 的抬升。估计用点过程似然；诊断用残余时间变换后的单位指数。</p><p><strong>标值。</strong> 价格变化、方向、跳幅度是标。标值 Hawkes 让幅度影响后续强度。对象变重，须有足够事件。不要对稀疏跳过程估满核。</p><h3 id="与微观结构模型" tabindex="-1">与微观结构模型 <a class="header-anchor" href="#与微观结构模型" aria-label="Permalink to &quot;与微观结构模型&quot;">​</a></h3><p>Kyle、Hasbrouck VAR 是离散时间交易与报价。点过程是连续时间到达。把 ACD 的 \\(\\psi\\) 当「下一笔等待」去切片执行，须再加方向与尺寸模型，否则只有时间没有路径。执行课（Obizhaeva–Wang 等）用强度当输入；本课只提供计量。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>短久期成串：条件强度高，像 GARCH 的波动聚集，但是在时间轴上。机制可以是信息到达、或算法切片、或自激励（一笔引来下一笔）。分支比不识别是信息还是羊群，只描述二阶到达结构。新闻抬 \\(\\mu(t)\\) 是可观测强度，自激励是内生；两者都使 RV 在该段更噪。</p><p>残余分析：时间变换 \\(\\Lambda(t)=\\int\\lambda\\) 后，事件应像单位泊松。过离散、簇拥说明核太短或缺季节。这与 ARMA 残差白噪声诊断平行，对象换成点。</p><p><span class="marginnote">把成交点过程估完，并不能修正价格噪声。\\(\\varepsilon\\) 仍在 \\(Y\\) 上。点过程帮你理解 \\(n\\) 与繁忙，IV 仍要用核/预平均/TSRV。</span></p><h3 id="到业务时间的交接" tabindex="-1">到业务时间的交接 <a class="header-anchor" href="#到业务时间的交接" aria-label="Permalink to &quot;到业务时间的交接&quot;">​</a></h3><p>墙钟上的季节与点过程纠缠：开盘 \\(\\lambda\\) 高。把时间轴按成交量重标，泊松更齐，ACD 的季节负担下降。Mandelbrot–Taylor、Ané–Geman、Clark 的从属过程是下一课：价格是业务时间上的较齐过程。本课的 \\(\\lambda(t)\\) 是墙钟强度，下一课把 \\(t\\) 变形。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>高频多元 Hawkes 参数多、易近临界不稳定。隔夜、竞价、拍卖不是同一点过程，应切段。监管批次、集合竞价没有「等待成交」的同一含义。</p><p>工程：单资产用 ACD + 季节 + 公告干预；交互到达用低维 Hawkes。不要对全市场每对估 Hawkes。不要用久期预测替代价格预测。已有 ACD 专课，本课不重复系数公式。下一课：业务时间时钟。</p>',24)),(e(),l(A,null,{default:i(()=>[d(r,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E4%BA%8B%E4%BB%B6%E7%82%B9%20N(t)%22%5D%20--%3E%20ACD%5B%22ACD%3A%20%E6%9D%A1%E4%BB%B6%E4%B9%85%E6%9C%9F%20%CF%88%22%5D%0A%20%20N%20--%3E%20HW%5B%22Hawkes%3A%20%E5%BC%BA%E5%BA%A6%20%CE%BB(t)%22%5D%0A%20%20NEWS%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%E5%8E%86%22%5D%20--%3E%20MU%5B%22%E6%8A%AC%E5%8D%87%20%CE%BC(t)%20%E6%88%96%E5%B9%B2%E9%A2%84%22%5D%0A%20%20MU%20--%3E%20HW%0A%20%20MU%20--%3E%20ACD%0A%20%20N%20--%3E%20NCOUNT%5B%22%E5%AE%9E%E7%8E%B0%E7%9A%84%20n%20%E8%BF%9B%E5%85%A5%20RV%20%E5%99%AA%E5%A3%B0%E9%A1%B9%22%5D%0A%20%20ACD%20--%3E%20BT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E6%8A%8A%20t%20%E6%8D%A2%E6%88%90%E4%B8%9A%E5%8A%A1%E6%97%B6%E9%97%B4%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>点过程对到达建模（ACD 久期或 Hawkes 强度），对象不是下一笔价格。</li><li>季节与新闻应进 \\(\\mu(t)\\) 或 \\(\\psi\\)，否则自激励吸收闹钟。</li><li>繁忙提高 \\(n\\)，朴素 RV 更噪；点过程解释采样内生，不替代噪声修正。</li><li>会话边界必须切断；多元核易过拟合。</li><li>出处：Engle and Russell, <em>Econometrica</em>, 1998；Hawkes, <em>Biometrika</em>, 1971；新闻强度与高频发现接 Andersen 等；细节估计见已有 <a href="/quant/acd-duration">ACD</a> 课。</li></ul>',2))])}const b=s(E,[["render",h]]);export{D as __pageData,b as default};
